func TestReceiverCompositionMixedAgentBothStores(t *testing.T) {
	for _, backend := range []string{"sqlite", "postgres"} {
		t.Run(backend, func(t *testing.T) {
			root := canonicalrouting.CopyReceiverMixedAgent(t)
			opts := cliapp.ServeOptions{SourceRoot: root, PlatformSpecPath: defaultPlatformSpecPath, APIListenAddr: "127.0.0.1:0", MCPListenAddr: "127.0.0.1:0", SelfCheck: true, Verbose: true, TestOutboxSweeperConfig: servedEventPublishProofOutboxSweeperConfig()}
			var db *sql.DB
			var diagnosticStore any
			var reader receiverProofStateReader
			var deliveryReader servedRunDeliveryReader
			captureSelectedRuntimePersistence(t, func(p serveRuntimePersistence) {
				deliveryReader = p.deps.DeliveryStore.SummarizeRun
			})
			captureSelectedRuntimePersistence(t, func(p serveRuntimePersistence) {
				diagnosticStore = p.deps.EventStore
				reader = requireReceiverProofStateReader(t, p.deps.EventStore)
				db, _, _ = selectedRuntimeStoreForTest(t, p)
			})
			if backend == "sqlite" {
				unsetStoreSelectorEnv(t)
				opts.ConfigPath = writeMockAgentRuntimeConfig(t, "sqlite", filepath.Join(t.TempDir(), "receiver.sqlite"))
			} else {
				dsn := testutil.StartEmptyPostgresDSN(t)
				previous := buildStoresForServe
				buildStoresForServe = func(ctx context.Context, selection backendselection.Selection, cfg *config.Config) (*selectedStoreOwner, error) {
					if selection.Backend != backendselection.BackendPostgres {
						t.Fatal("mixed receiver fixture selected another backend")
					}
					return storeselected.OpenRuntime(ctx, storeselected.RuntimeRequest{Selection: selection, PostgresDSN: dsn, SessionLockTTL: runtimeSessionLockTTL(cfg)})
				}
				t.Cleanup(func() {
					buildStoresForServe = previous
				})
				opts.ConfigPath = writeMockAgentRuntimeConfig(t, "postgres", "")
				opts.StoreMode, opts.StoreModeSet = backendselection.BackendPostgres.String(), true
			}
			endpoint, runtime := startOwnedMockLifecycleFollowUpRuntime(t, opts)
			bundle := servedEventPublishFixtureBundleHash(t, root)
			seed := requireServedEventPublishRPCResult(t, endpoint, map[string]any{"event_name": "work.seeded", "bundle_hash": bundle, "payload": map[string]any{"seed": true}, "idempotency_key": "mixed-agent-seed"})
			requireServedEventPublishEntityState(t, reader, backend, seed.RunID, flowidentity.EntityID("sink"), "active")
			waitServedRunDeliveryQuiescence(t, deliveryReader, seed.RunID)
			var childID, parentID string
			if err := db.QueryRow(`SELECT entity_id FROM entity_state WHERE run_id=$1 AND flow_instance='sink'`, seed.RunID).Scan(&childID); err != nil {
				t.Fatal(err)
			}
			if err := db.QueryRow(`SELECT entity_id FROM entity_state WHERE run_id=$1 AND flow_instance<>'sink'`, seed.RunID).Scan(&parentID); err != nil {
				t.Fatal(err)
			}
			if childID == parentID || childID == "" {
				t.Fatal("seed did not establish distinct receiving ownership")
			}
			published := requireServedEventPublishRPCResult(t, endpoint, map[string]any{"event_name": "work.requested", "run_id": seed.RunID, "source_event_id": seed.EventID, "payload": map[string]any{"seed": true}, "idempotency_key": "mixed-agent"})
			waitServedRunDeliveryQuiescence(t, deliveryReader, published.RunID)
			var agents, nodes, turns int
			if err := db.QueryRow(`SELECT count(*) FROM event_deliveries WHERE run_id=$1 AND subscriber_type='agent' AND status='delivered'`, published.RunID).Scan(&agents); err != nil {
				t.Fatal(err)
			}
			if err := db.QueryRow(`SELECT count(*) FROM event_deliveries WHERE run_id=$1 AND subscriber_type='node' AND status='delivered'`, published.RunID).Scan(&nodes); err != nil {
				t.Fatal(err)
			}
			if err := db.QueryRow(`SELECT count(*) FROM agent_turns WHERE run_id=$1 AND execution_mode='mock'`, published.RunID).Scan(&turns); err != nil {
				t.Fatal(err)
			}
			if agents != 1 || nodes != 4 || turns != 1 {
				if failure, err := storetest.ReadGateDeadLetterFailure(context.Background(), diagnosticStore, published.EventID); err == nil {
					t.Logf("receiver failure: %s", failure)
				}
				t.Fatalf("mixed real execution agents/nodes/turns=%d/%d/%d\n%s", agents, nodes, turns, servedInspectionRunDebugSummary(reader, published.RunID))
			}
			rows, err := db.Query(`SELECT d.subscriber_type,CAST(d.delivery_target_route AS TEXT) FROM event_deliveries d JOIN events e ON e.event_id=d.event_id WHERE d.run_id=$1 AND e.event_name='work.completed'`, published.RunID)
			if err != nil {
				t.Fatal(err)
			}
			nodeOwners, agentOwners := 0, 0
			for rows.Next() {
				var subscriberType, raw string
				var owner events.DeliveryTargetOwnership
				if err := rows.Scan(&subscriberType, &raw); err != nil {
					t.Fatal(err)
				}
				if err := json.Unmarshal([]byte(raw), &owner); err != nil {
					t.Fatal(err)
				}
				if owner.Route().FlowID != "sink" || owner.Route().FlowInstance != "sink" {
					t.Fatalf("mixed %s recipient borrowed another flow: %s", subscriberType, raw)
				}
				switch subscriberType {
				case "node":
					if owner.Route().EntityID != childID || owner.Code() != "existing_entity" {
						t.Fatalf("node lost its constructed child ownership: %s", raw)
					}
					nodeOwners++
				case "agent":
					if owner.Route().EntityID != "" || owner.Code() != "entityless_receiver" {
						t.Fatalf("agent borrowed the node's constructed ownership: %s", raw)
					}
					agentOwners++
				default:
					t.Fatalf("unexpected mixed subscriber type %q", subscriberType)
				}
			}
			if err := rows.Err(); err != nil {
				t.Fatal(err)
			}
			rows.Close()
			if nodeOwners != 1 || agentOwners != 1 {
				t.Fatalf("mixed event owners node/agent=%d/%d, want 1/1", nodeOwners, agentOwners)
			}
			requireReceiverPublicReadback(t, servedControlProofRuntime{ReadRunDeliveries: deliveryReader, Endpoint: endpoint, DB: db, Backend: backend, Runtime: runtime, BundleHash: bundle}, published.RunID)
		})
	}
}

