		if err := rows.Scan(&id, &record.eventID, &record.status, &raw); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal([]byte(raw), &record.owner); err != nil {
			t.Fatal(err)
		}
		want[id] = record
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	rows.Close()
	requireReceiverPublicReadbackEvidence(t, rt.Endpoint, runID, want)
}

